    ('3315cd99-84ed-4e95-b743-fe75fb4c7654'::uuid, 'site_type', 'Temple complex', 'Temple', 'fields-wd1-2026-09-26d-s005:3315cd99-84ed-4e95-b743-fe75fb4c7654:site_type', 'fields-wd1-2026-09-26d-s005 (wd1-replace): ''Temple complex'' -> ''Temple''', '[{"source": "https://danasvistas.com/en/attraction/almofala-tower-figueira-de-castelo-rodrigo", "url": "https://danasvistas.com/en/attraction/almofala-tower-figueira-de-castelo-rodrigo", "quote": "The Torre de Almofala is of Roman foundation, which was originally used as a temple.", "outcome": "found"}, {"source": "https://www.guiadacidade.pt/pt/poi-torre-de-almofala-15046", "url": "https://www.guiadacidade.pt/pt/poi-torre-de-almofala-15046", "quote": "As escavações feitas nesta zona, atestam a existência de uma cidade romana e base da Torre de Almofala, tem as características da arquitectura dos templos romanos.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0336)", "decision": "replace", "status": "MISSING", "reasoning": "Dana''s Vistas says the Torre de Almofala was originally a Roman temple and Guia da Cidade that its base has the features of Roman temples (templos); it is a single temple.", "value_page": null}]'::jsonb),
